import{auth}from"@/auth";import{db}from"@/lib/db";import{aiProvider}from"@/lib/ai";import{readStored}from"@/lib/storage/local-storage";import{enforceRateLimit}from"@/lib/rate-limit";export async function POST(req:Request){const s=await auth();if(!s?.user)return Response.json({error:"Unauthorized"},{status:401});await enforceRateLimit("AI_SUGGEST",s.user.id,20,3600000);const{id}=await req.json();const a=await db.artwork.findUnique({where:{id},include:{asset:true}});if(!a?.asset||a.authorId!==s.user.id)return Response.json({error:"Not found"},{status:404});const suggestion=await aiProvider.analyzeImage(await readStored(a.asset.previewKey));await db.aiSuggestion.create({data:{artworkId:id,provider:aiProvider.name,model:aiProvider.model,kind:"FULL_ANALYSIS",suggestion}});return Response.json(suggestion)}